<!DOCTYPE html><html><form action="index.php" method="POST">    <label>Kullanıcı Adı:</label>    <input type="text" name="name">    <label>Şifre:</label>    <input type="password" name="password">    <button type="submit">Oluştur</button></form><body>    <?phpif (isset($_POST['name'], $_POST['password'])) {    $name   = $_POST['name'];    $sifre  = $_POST['password'];    if ($name == 10 && $sifre == 15) {        echo "Kullanıcı ismi: $name<br>";        echo "Şifreniz: $sifre";    } else {        echo "Kullanıcı adı 10, şifre ise 15 olmalıdır.";    }} else {    echo "Lütfen kullanıcı adı ve şifre giriniz.";}?></body></html>